# subconverter 全自动闭环开发与运维脚本 # 阶段：诊断 -> 修复 -> CI -> CD -> 验证 ======================================================================= Write-Host "========================================" -ForegroundColor Cyan Write-Host "subconverter 全自动闭环运维系统 v1.0" -ForegroundColor Cyan Write-Host "========================================" -ForegroundColor Cyan Write-Host "" # ==================== 配置区域 ==================== # 项目配置 $ProjectRoot = Resolve-Path (Split-Path -Parent $MyInvocation.MyCommand.Path) $GitRemote = "origin" $GitBranch = "main" # GitHub 配置（请替换为实际值） $GitHubOwner = "whua898" $GitHubRepo = "subconverter" $GitHubPAT = "" # 服务配置 $ServiceUrl = "http://localhost:25500" $TestSubscriptionUrl = "http://35.212.140.13:28038/56ff8aef-19a9-4043-8d4c-d38361c8f651/v2rayn" $TestTargets = @("v2ray", "mixed", "clash") # 超时配置（秒） $GitHubTimeout = 900 # 15分钟 $DockerTimeout = 120 $ApiTimeout = 30 # ==================== 日志函数 ==================== $script:IterationCount = 0 function Write-TimestampedStep { param( [string]$Message, [string]$Color = "White" ) $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss" Write-Host "[$timestamp] $Message" -ForegroundColor $Color } function Log-IterationStart { $script:IterationCount++ Write-Host "" Write-Host "========================================" -ForegroundColor Magenta Write-Host " === 第 $($script:IterationCount) 次迭代开始 ===" -ForegroundColor Magenta Write-Host "========================================" -ForegroundColor Magenta } function Log-Success { Write-TimestampedStep "✓ $_" "Green" } function Log-Error { Write-TimestampedStep "✗ $_" "Red" } function Log-Warning { Write-TimestampedStep "⚠ $_" "Yellow" } function Log-Info { Write-TimestampedStep "ℹ $_" "Cyan" } # ==================== 阶段1：故障诊断 ==================== function Test-ServiceHealth { Write-Host "" Write-Host "[阶段1] 故障诊断" -ForegroundColor Blue Write-Host "-------------------" -ForegroundColor Gray Log-Info "检查 subconverter 服务健康状态" try { $response = Invoke-WebRequest -Uri "$ServiceUrl/version" -Method GET -TimeoutSec $ApiTimeout -ErrorAction Stop Log-Success "subconverter 服务运行正常" Log-Info "版本信息: $($response.Content)" return $true } catch { Log-Error "无法连接到 subconverter 服务: $_" Log-Info "请确保服务在 $ServiceUrl 运行" return $false } } function Test-SubscriptionConversion { param( [string]$Target, [string]$SubscriptionUrl = $TestSubscriptionUrl ) $url = "$ServiceUrl/sub?target=$Target&url=$([uri]::EscapeDataString($SubscriptionUrl))" try { Log-Info "测试 target=$Target" $response = Invoke-WebRequest -Uri $url -Method GET -TimeoutSec $ApiTimeout -ErrorAction Stop $statusCode = $response.StatusCode $content = $response.Content # 检查是否为 Base64 $isBase64 = $false $decodedContent = "" try { $bytes = [Convert]::FromBase64String($content) $decodedContent = [System.Text.Encoding]::UTF8.GetString($bytes) $isBase64 = $true } catch { $isBase64 = $false } $nodeCount = 0 $protocolStats = @{} if ($isBase64) { $lines = $decodedContent -split "`n" | Where-Object { $_.Trim() -ne "" } $nodeCount = $lines.Count # 统计协议 $protocolStats.vmess = ($lines | Where-Object { $_ -match "^vmess://" }).Count $protocolStats.vless = ($lines | Where-Object { $_ -match "^vless://" }).Count $protocolStats.trojan = ($lines | Where-Object { $_ -match "^trojan://" }).Count $protocolStats.ss = ($lines | Where-Object { $_ -match "^ss://" }).Count $protocolStats.ssr = ($lines | Match-Object { $_ -match "^ssr://" }).Count $protocolStats.hysteria2 = ($lines | Where-Object { $_ -match "^hysteria2://" }).Count $protocolStats.tuic = ($lines | Where-Object { $_ -match "^tuic://" }).Count } # 输出结果 Write-Host "" Write-Host " [$Target] 验证报告" -ForegroundColor Yellow Write-Host " - 状态码: $statusCode" -ForegroundColor Gray Write-Host " - 内容长度: $($content.Length)" -ForegroundColor Gray Write-Host " - Base64 有效: $isBase64" -ForegroundColor Gray if ($isBase64) { Write-Host " - 节点总数: $nodeCount" -ForegroundColor Gray foreach ($proto in $protocolStats.Keys) { if ($protocolStats[$proto] -gt 0) { Write-Host " - $proto`: $($protocolStats[$proto])" -ForegroundColor Gray } } } # 判定是否成功 if ($statusCode -eq 200 -and $isBase64 -and $nodeCount -ge 1) { Write-Host " - 验证结果: ✓ 通过" -ForegroundColor Green return @{ Success = $true; Target = $Target; StatusCode = $statusCode; IsBase64 = $isBase64; NodeCount = $nodeCount; ProtocolStats = $protocolStats } } else { Write-Host " - 验证结果: ✗ 失败" -ForegroundColor Red return @{ Success = $false; Target = $Target; StatusCode = $statusCode; IsBase64 = $isBase64; NodeCount = $nodeCount; Reason = if ($statusCode -ne 200) { "HTTP 状态码异常" } elseif (-not $isBase64) { "输出非 Base64 格式" } else { "节点数为 0" } } } } catch { Write-Host " - 错误: $_" -ForegroundColor Red return @{ Success = $false; Target = $Target; Error = $_.Exception.Message } } } function Analyze-Failure { param( [hashtable]$TestResult ) Log-Warning "失败分析" $reason = $TestResult.Reason if (-not $reason) { $reason = $TestResult.Error } Write-Host " 失败原因: $reason" -ForegroundColor Yellow Write-Host "" Write-Host " 修复策略:" -ForegroundColor Cyan if ($reason -match "节点数为 0") { Write-Host " 1. 检查订阅源是否包含 v2rayN 支持的协议" -ForegroundColor Gray Write-Host " 2. 验证 proxyToSingle 函数的协议选择参数" -ForegroundColor Gray Write-Host " 3. 检查解析器是否正确识别节点类型" -ForegroundColor Gray } elseif ($reason -match "非 Base64") { Write-Host " 1. 检查 proxyToSingle 函数的输出编码" -ForegroundColor Gray Write-Host " 2. 验证 urlSafeBase64Encode 函数是否正确定义" -ForegroundColor Gray Write-Host " 3. 检查是否有未处理的异常导致返回空" -ForegroundColor Gray } else { Write-Host " 1. 检查服务日志获取详细错误信息" -ForegroundColor Gray Write-Host " 2. 验证网络连接和订阅源可达性" -ForegroundColor Gray Write-Host " 3. 检查配置文件中的参数设置" -ForegroundColor Gray } return $reason } # ==================== 阶段2：代码修复 ==================== function Get-CurrentCodeIssue { Log-Info "分析代码问题（需要人工确认或查看日志）" # 这里可以根据诊断结果提供具体修复建议 $issues = @( "1. 检查 Src/handler/interfaces.cpp 中 proxyToSingle 函数的调用参数" "2. 验证 base64Encode/urlSafeBase64Encode 函数的实现" "3. 检查节点解析是否正确填充 protocol 字段" ) Write-Host "" Write-Host "当前已知代码结构：" -ForegroundColor Cyan Write-Host "- target=v2ray 调用: proxyToSingle(nodes, 127, ext)" -ForegroundColor Gray Write-Host "  其中 127 = SS(1) + SSR(2) + VMess(4) + Trojan(8) + Hysteria2(16) + VLESS(32) + TUIC(64)" -ForegroundColor Gray Write-Host "" Write-Host "可能的修复方向：" -ForegroundColor Yellow foreach ($issue in $issues) { Write-Host " $issue" -ForegroundColor Gray } return $issues } function Invoke-CodeFix { param( [string]$FixStrategy ) Log-Info "准备应用修复（当前为占位函数）" Log-Info "实际修复需要根据具体问题修改 C++ 源代码" # TODO: 根据故障分析结果，自动修改源代码 return $true } # ==================== 阶段3：Git 集成与 CI ==================== function Push-ToGitHub { param( [string]$CommitMessage = "fix: auto-fix v2rayN base64 output" ) Write-Host "" Write-Host "[阶段3] Git 集成与 CI" -ForegroundColor Blue Write-Host "-------------------" -ForegroundColor Gray Log-Info "检查 Git 仓库状态" Push-Location $ProjectRoot try { git status | Out-Null if ($LASTEXITCODE -ne 0) { Log-Error "不是 Git 仓库" return $false } # 检查是否有未提交的更改 $status = git status --porcelain if ([string]::IsNullOrWhiteSpace($status)) { Log-Warning "没有未提交的更改，跳过 Git 操作" return $true } Log-Info "添加所有更改" git add . if ($LASTEXITCODE -ne 0) { Log-Error "git add 失败" return $false } Log-Info "提交更改" git commit -m $CommitMessage if ($LASTEXITCODE -ne 0) { Log-Error "git commit 失败" return $false } $commitHash = git rev-parse HEAD Log-Success "提交完成: $commitHash" # 推送 Log-Info "推送到远程仓库" git push origin $GitBranch if ($LASTEXITCODE -ne 0) { Log-Error "git push 失败" return $false } Log-Success "推送成功" return $true } catch { Log-Error "Git 操作异常: $_" return $false } finally { Pop-Location } } function Wait-GitHubActions { Write-Host "" Log-Info "等待 GitHub Actions 编译完成（超时: $([math]::Floor($GitHubTimeout/60)) 分钟）" if ([string]::IsNullOrWhiteSpace($GitHubPAT)) { Log-Warning "未配置 GitHub PAT，跳过 CI 等待" Log-Info "请手动检查 GitHub Actions 状态后继续" return $true } $headers = @{ Authorization = "token $GitHubPAT" } $startTime = Get-Date $checkInterval = 30 while ($true) { $elapsed = (Get-Date) - $startTime if ($elapsed.TotalSeconds -gt $GitHubTimeout) { Log-Error "编译超时（$([math]::Floor($elapsed.TotalMinutes)) 分钟）" Log-Info "请手动检查 Actions 状态后重新运行" return $false } try { # 查询最新的 workflow run $runsUrl = "https://api.github.com/repos/$GitHubOwner/$GitHubRepo/actions/runs?branch=$GitBranch&per_page=1" $response = Invoke-RestMethod -Uri $runsUrl -Headers $headers -TimeoutSec 10 -ErrorAction Stop if ($response.workflow_runs.Count -eq 0) { Log-Warning "未找到 Workflow 运行记录" Start-Sleep -Seconds $checkInterval continue } $run = $response.workflow_runs[0] $status = $run.status $conclusion = $run.conclusion Write-Host "`r[CI] 状态: $status | 结论: $conclusion | 运行ID: $($run.id)" -NoNewline -ForegroundColor Yellow switch ($status) { "completed" { if ($conclusion -eq "success") { Write-Host "" Log-Success "编译成功完成" Log-Info "Workflow URL: $($run.html_url)" return $true } else { Write-Host "" Log-Error "编译失败" Log-Info "查看日志: $($run.html_url)" # 下载失败日志 Download-ActionLogs -RunId $run.id -Headers $headers return $false } } "in_progress" { Write-Host " (剩余时间: $([math]::Max(0, [math]::Floor(($GitHubTimeout - $elapsed.TotalSeconds)/60))) 分钟)" -NoNewline } default { Log-Info "等待中." } } } catch { if ($_.Exception.Message -match "rate limit") { Log-Warning "GitHub API Rate Limit，休眠 60 秒." Start-Sleep -Seconds 60 } else { Log-Warning "查询 GitHub API 失败: $_" Start-Sleep -Seconds $checkInterval } } Start-Sleep -Seconds $checkInterval } } function Download-ActionLogs { param( [int]$RunId, [hashtable]$Headers ) Log-Info "下载编译日志分析错误" try { $logsUrl = "https://api.github.com/repos/$GitHubOwner/$GitHubRepo/actions/runs/$RunId/logs" $logs = Invoke-RestMethod -Uri $logsUrl -Headers $Headers -TimeoutSec 30 if ($logs) { Write-Host "" Log-Info "日志分析（关键错误）:" -ForegroundColor Red # 查找编译错误 $errors = $logs -split "`n" | Where-Object { $_ -match "error:|Error|fatal|FAILED" } | Select-Object -First 20 foreach ($err in $errors) { Write-Host " $err" -ForegroundColor Red } } } catch { Log-Warning "日志下载失败: $_" } } # ==================== 阶段4：Docker 部署 ==================== function Update-DockerContainer { Write-Host "" Write-Host "[阶段4] Docker 部署" -ForegroundColor Blue Write-Host "-------------------" -ForegroundColor Gray Log-Info "拉取最新镜像" $imageName = "ghcr.io/$GitHubOwner/$GitHubRepo:latest" try { $pullResult = docker pull $imageName 2>&1 if ($LASTEXITCODE -ne 0) { Log-Error "Docker 镜像拉取失败" Log-Info "尝试使用本地构建." return $false } Log-Success "镜像拉取成功" # 查找并停止旧容器 Log-Info "查找运行的容器" $containers = docker ps --filter "ancestor=$imageName" --format "{{.ID}}" if ($containers) { foreach ($containerId in $containers) { Log-Info "停止旧容器: $containerId" docker stop $containerId | Out-Null } # 删除旧容器 docker rm $containers | Out-Null } Log-Info "启动新容器" $containerId = docker run -d --name subconverter -p 25500:25500 $imageName if ($LASTEXITCODE -ne 0) { Log-Error "容器启动失败" return $false } Log-Success "容器启动成功: $containerId" # 就绪检查 Log-Info "等待服务就绪（5 秒）." Start-Sleep -Seconds 5 # 验证容器运行状态 $health = docker inspect $containerId --format "{{.State.Status}}" if ($health -eq "running") { Log-Success "容器运行正常" return $true } else { Log-Error "容器状态异常: $health" return $false } } catch { Log-Error "Docker 操作异常: $_" return $false } } # ==================== 阶段5：验证闭环 ==================== function Test-SubscriptionConversion { Write-Host "" Write-Host "[阶段5] 功能验证" -ForegroundColor Blue Write-Host "-------------------" -ForegroundColor Gray Log-Info "执行订阅转换测试" $allPassed = $true $results = @() foreach ($target in $TestTargets) { $result = Test-SubscriptionConversion -Target $target $results += $result if (-not $result.Success) { $allPassed = $false } } # 输出验证报告 Write-Host "" Write-Host "验证报告汇总：" -ForegroundColor Cyan foreach ($result in $results) { $statusIcon = if ($result.Success) { "✓" } else { "✗" } $statusColor = if ($result.Success) { "Green" } else { "Red" } Write-Host " $statusIcon target=$($result.Target): " -NoNewline -ForegroundColor $statusColor if ($result.Success) { Write-Host "通过 (节点数: $($result.NodeCount))" } else { Write-Host "失败 ($($result.Reason))" } } return $allPassed } # ==================== 主执行流程 ==================== function Main { param( [switch]$AutoLoop = $false, [int]$MaxIterations = 10 ) Log-IterationStart while ($true) { if ($script:IterationCount -ge $MaxIterations) { Log-Warning "达到最大迭代次数 ($MaxIterations)，停止循环" break } # 阶段1：诊断 $serviceOk = Test-ServiceHealth if (-not $serviceOk) { Log-Error "服务不可用，等待5秒后重试." Start-Sleep -Seconds 5 continue } $testResult = Test-SubscriptionConversion -Target "v2ray" # 阶段5：验证闭环 if ($testResult.Success) { Log-Success "验证通过！任务完成！" break } else { $failureReason = Analyze-Failure -TestResult $testResult } # 阶段2：修复（这里需要人工介入或已有自动修复逻辑） Log-Info "检查是否需要代码修复" $issues = Get-CurrentCodeIssue Log-Info "请审查上述问题并决定修复策略" Log-Info "演示模式：演示脚本流程完成" break # 演示模式退出 if ($AutoLoop) { Log-Info "自动循环模式：等待 5 秒后进行下一次迭代." Start-Sleep -Seconds 5 } else { Log-Warning "单项模式完成。使用 -AutoLoop 参数可开启循环。" break } } } # ==================== 入口 ==================== # 支持参数 $AutoLoop = $false $MaxIterations = 10 foreach ($arg in $args) { switch ($arg) { "-AutoLoop" { $AutoLoop = $true } "-MaxIterations" { $MaxIterations = $args[$args.IndexOf($arg) + 1] } "-Subscription" { $TestSubscriptionUrl = $args[$args.IndexOf($arg) + 1] } "-ServiceUrl" { $ServiceUrl = $args[$args.IndexOf($arg) + 1] } "-GitHubPAT" { $GitHubPAT = $args[$args.IndexOf($arg) + 1] } "-GitHubOwner" { $GitHubOwner = $args[$args.IndexOf($arg) + 1] } "-GitHubRepo" { $GitHubRepo = $args[$args.IndexOf($arg) + 1] } } } # 执行主流程 Main -AutoLoop:$AutoLoop -MaxIterations $MaxIterations